var hLabel = haloText(labelG.text('h'));
var thLabel = haloText(labelG.text('θ').font({ size: 20 }));

var roleLeader = calloutG.line(0, 0, 0, 0).stroke({ color: warm, width: 1.3, opacity: 0.7 });
var roleBg = calloutG.rect(118, 32).radius(7).fill({ color: '#ffffff', opacity: 0.94 }).stroke({ color: warm, width: 1.2, opacity: 0.75 });
var roleText = calloutG.text('').font({ family: 'Georgia, Times New Roman, serif', size: 18, style: 'italic' }).fill(warm);
var relationG = draw.group();
var relBg = relationG.rect(210, 68).radius(9).fill({ color: '#ffffff', opacity: 0.96 }).stroke({ color: warm, width: 1.4 });
var relText1 = relationG.text('').font({ family: 'Georgia, Times New Roman, serif', size: 20, style: 'italic' }).fill(black);
var relText2 = relationG.text('').font({ family: 'Arial, sans-serif', size: 12 }).fill('#444444');
relationG.hide();
calloutG.hide();

var hitBase = hitG.line(0, 0, 0, 0).stroke({ color: '#000', width: 22, opacity: 0 }).attr({ 'pointer-events': 'stroke' });
var hitVert = hitG.line(0, 0, 0, 0).stroke({ color: '#000', width: 22, opacity: 0 }).attr({ 'pointer-events': 'stroke' });
var hitHyp = hitG.line(0, 0, 0, 0).stroke({ color: '#000', width: 22, opacity: 0 }).attr({ 'pointer-events': 'stroke' });

hitBase.css('cursor', 'pointer')
  .on('mousemove', function (e) { showTooltip('a is adjacent to θ because it touches the reference angle.', e); })
  .on('mouseleave', function () { hideTooltip(); })
  .on('click', function () { chooseSide('a', true); });
hitVert.css('cursor', 'pointer')
  .on('mousemove', function (e) { showTooltip('p is opposite θ because it faces the reference angle across the triangle.', e); })
  .on('mouseleave', function () { hideTooltip(); })
  .on('click', function () { chooseSide('p', true); });
hitHyp.css('cursor', 'pointer')
  .on('mousemove', function (e) { showTooltip('h is the hypotenuse, the side across from the right angle.', e); })
  .on('mouseleave', function () { hideTooltip(); })
  .on('click', function () { chooseSide('h', true); });

relationG.css('cursor', 'pointer')
  .on('mousemove', function (e) { showTooltip('The known side pair names the inverse trig function.', e); })
  .on('mouseleave', function () { hideTooltip(); })
  .on('click', function () {
    showPopup('Inverse trig choice', 'A ratio involving opposite over hypotenuse points to sine, adjacent over hypotenuse points to cosine, and opposite over adjacent points to tangent. The inverse function undoes that ratio to recover θ.');
  });

function endpoints() {
  var r = thetaDeg * Math.PI / 180;
  var B = { x: A.x + HYP * Math.cos(r), y: A.y };
  var C = { x: B.x, y: A.y - HYP * Math.sin(r) };
  return { A: A, B: B, C: C, a: Math.cos(r), p: Math.sin(r), h: 1 };
}

function arcPath(cx, cy, rad, deg) {
  var ex = cx + rad * Math.cos(deg * Math.PI / 180);
  var ey = cy - rad * Math.sin(deg * Math.PI / 180);
  return 'M ' + (cx + rad) + ' ' + cy + ' A ' + rad + ' ' + rad + ' 0 0 0 ' + ex + ' ' + ey;
}

function setLine(el, P, Q) {
  el.plot(P.x, P.y, Q.x, Q.y);
}

function updateScene() {
  var e = endpoints();
  var A0 = e.A, B = e.B, C = e.C;

  setLine(baseLine, A0, B);
  setLine(vertLine, B, C);
  setLine(hypLine, A0, C);
  setLine(hitBase, A0, B);
  setLine(hitVert, B, C);
  setLine(hitHyp, A0, C);

  var guideY = A0.y + 42;
  var guideX = B.x + 32;
  baseGuide.plot(A0.x, guideY, B.x, guideY);
  heightGuide.plot(guideX, B.y, guideX, C.y);
  baseTick1.plot(A0.x, guideY - 6, A0.x, guideY + 6);
  baseTick2.plot(B.x, guideY - 6, B.x, guideY + 6);
  heightTick1.plot(guideX - 6, B.y, guideX + 6, B.y);
  heightTick2.plot(guideX - 6, C.y, guideX + 6, C.y);

  setLine(baseHL, A0, B);
  setLine(vertHL, B, C);
  setLine(hypHL, A0, C);

  thetaArc.plot(arcPath(A0.x, A0.y, 38, thetaDeg));
  thetaHL.plot(arcPath(A0.x, A0.y, 45, thetaDeg));

  var sq = 22;
  rightSq.plot('M ' + (B.x - sq) + ' ' + B.y + ' L ' + (B.x - sq) + ' ' + (B.y - sq) + ' L ' + B.x + ' ' + (B.y - sq));

  aLabel.center((A0.x + B.x) / 2, A0.y + 28);
  pLabel.center(B.x + 20, (B.y + C.y) / 2);
  hLabel.center((A0.x + C.x) / 2 - 6, (A0.y + C.y) / 2 - 26);
  thLabel.center(A0.x + 43, A0.y - 16);

  updateHighlightsAndCallouts(e);
}

function roleForSide(side) {
  if (side === 'a') return { role: 'adjacent', popup: 'The base a is adjacent to θ because it is one of the two sides forming the angle. It is not the hypotenuse because it also touches the right angle.' };
  if (side === 'p') return { role: 'opposite', popup: 'The vertical side p is opposite θ because it does not touch the reference angle. It faces θ across the triangle.' };
  return { role: 'hypotenuse', popup: 'The slanted side h is the hypotenuse because it lies across from the right angle. This role does not depend on which acute angle is chosen.' };
}

function chooseSide(side, openPopup) {
  selectedSide = side;
  relationVisible = false;
  updateScene();
  if (openPopup) {
    var info = roleForSide(side);
    showPopup(info.role, info.popup);
  }
}

function updateHighlightsAndCallouts(e) {
  var pair = relationVisible && ratioInfo && ratioInfo.sides ? ratioInfo.sides : [];
  var showA = selectedSide === 'a' || pair.indexOf('a') >= 0;
  var showP = selectedSide === 'p' || pair.indexOf('p') >= 0;
  var showH = selectedSide === 'h' || pair.indexOf('h') >= 0;

  baseHL.attr({ opacity: showA ? 0.82 : 0 });
  vertHL.attr({ opacity: showP ? 0.82 : 0 });
  hypHL.attr({ opacity: showH ? 0.82 : 0 });
  thetaHL.attr({ opacity: (showA || showP || showH || relationVisible) ? 0.78 : 0 });

  if (selectedSide) {
    var data = roleForSide(selectedSide);
    roleText.text(data.role);
    var sidePt, bx, by, tx, ty;
    if (selectedSide === 'a') {
      sidePt = { x: (e.A.x + e.B.x) / 2, y: e.A.y };
      bx = sidePt.x - 59; by = e.A.y + 54; tx = bx + 15; ty = by + 6;
      roleLeader.plot(sidePt.x, sidePt.y + 3, bx + 59, by);
    } else if (selectedSide === 'p') {
      sidePt = { x: e.B.x, y: (e.B.y + e.C.y) / 2 };
      bx = e.B.x + 38; by = sidePt.y - 16; tx = bx + 13; ty = by + 6;
      roleLeader.plot(sidePt.x + 3, sidePt.y, bx, by + 16);
    } else {
      sidePt = { x: (e.A.x + e.C.x) / 2, y: (e.A.y + e.C.y) / 2 };
      bx = sidePt.x - 44; by = sidePt.y - 64; tx = bx + 11; ty = by + 6;
      roleLeader.plot(sidePt.x, sidePt.y - 4, bx + 59, by + 32);
    }
    roleBg.move(bx, by);
    roleText.move(tx, ty);
    calloutG.show();
  } else {
    calloutG.hide();
  }

  if (relationVisible && ratioInfo) {
    relationG.show();
    relBg.move(360, 58);
    relText1.move(376, 70).text(ratioInfo.formula);
    relText2.move(376, 103).text(ratioInfo.detail);
  } else {
    relationG.hide();
  }
}

function classifyRatio(expr, val, e) {
  var s = String(expr).toLowerCase().replace(/\s+/g, '').replace(/[()]/g, '');
  var options = [
    { key: 'p/h', formula: 'θ = sin⁻¹(p/h)', detailName: 'opposite ÷ hypotenuse', sides: ['p', 'h'], value: e.p / e.h },
    { key: 'a/h', formula: 'θ = cos⁻¹(a/h)', detailName: 'adjacent ÷ hypotenuse', sides: ['a', 'h'], value: e.a / e.h },
    { key: 'p/a', formula: 'θ = tan⁻¹(p/a)', detailName: 'opposite ÷ adjacent', sides: ['p', 'a'], value: e.p / e.a }
  ];

  for (var i = 0; i < options.length; i++) {
    if (s === options[i].key) return options[i];
  }
  for (var j = 0; j < options.length; j++) {
    if (Math.abs(val - options[j].value) < 1e-7) return options[j];
  }
  return null;
}

function updateKnownRatio(src) {
  var input = document.getElementById('knownRatioInput');
  var slot = document.getElementById('ratioErr');
  var readout = document.getElementById('relationReadout');
  var e = endpoints();
  try {
    var fn = compileExpr(src, ['a', 'p', 'h']);
    var val = fn(e.a, e.p, e.h);
    if (!isFinite(val)) throw new Error('The ratio did not evaluate to a finite number.');
    var kind = classifyRatio(src, val, e);
    slot.style.display = 'none';
    slot.textContent = '';
    input.setAttribute('data-eq-valid', 'true');
    if (kind) {
      ratioInfo = {
        formula: kind.formula,
        detail: kind.detailName + ' ≈ ' + val.toFixed(3),
        sides: kind.sides
      };
      readout.textContent = kind.formula + ' because the known ratio is ' + kind.detailName + '.';
    } else {
      ratioInfo = {
        formula: 'Try p/h, a/h, or p/a',
        detail: 'This expression is valid, but it is not one of the three basic side-pair ratios.',
        sides: []
      };
      readout.textContent = 'Valid ratio ≈ ' + val.toFixed(3) + '. Try p/h, a/h, or p/a to select an inverse trig function.';
    }
    updateScene();
    return true;
  } catch (err) {
    slot.textContent = err.message;
    slot.style.display = '';
    input.setAttribute('data-eq-valid', 'false');
    return false;
  }
}

function update_thetaSlider(v) {
  thetaDeg = v;
  updateKnownRatio(document.getElementById('knownRatioInput').value);
  updateScene();
}

document.getElementById('knownRatioInput').addEventListener('input', function () {
  relationVisible = true;
  selectedSide = null;
  updateKnownRatio(this.value);
});
document.getElementById('knownRatioInput').addEventListener('focus', function () {
  relationVisible = true;
  selectedSide = null;
  updateKnownRatio(this.value);
});

var steps = [
  {
    title: 'Identify the reference angle',
    narration: 'The marked angle theta at the left vertex is the reference point for naming the sides. The labels a, p, and h describe each side’s role relative to theta, not merely its direction on the page.',
    state: { thetaSlider: 35 }
  },
  {
    title: 'Click each side role',
    narration: 'Click a side to highlight it with theta: a is adjacent because it touches theta, p is opposite because it faces theta, and h is the hypotenuse because it lies across from the right angle.',
    state: { thetaSlider: 35 }
  },
  {
    title: 'Change theta',
    narration: 'Drag theta wider and narrower. The triangle keeps a right angle, but the balance between opposite side p and adjacent side a changes continuously.',
    state: { thetaSlider: 60 }
  },
  {
    title: 'Choose the inverse trig relation',
    narration: 'Enter a known ratio such as p/h, a/h, or p/a. The matching inverse relation is highlighted, showing which formula recovers the unknown angle theta.',
    state: { thetaSlider: 35 }
  }
];

function applyStep(i) {
  currentStep = Math.max(0, Math.min(steps.length - 1, i));
  var step = steps[currentStep];
  if (step.state && step.state.thetaSlider != null) {
    var s = document.getElementById('thetaSliderInput');
    s.value = step.state.thetaSlider;
    document.getElementById('thetaSliderVal').value = step.state.thetaSlider;
    thetaDeg = +step.state.thetaSlider;
  }

  if (currentStep === 0) {
    selectedSide = null;
    relationVisible = false;
  } else if (currentStep === 1) {
    selectedSide = 'a';
    relationVisible = false;
  } else if (currentStep === 2) {
    selectedSide = 'p';
    relationVisible = false;
  } else {
    selectedSide = null;
    relationVisible = true;
    document.getElementById('knownRatioInput').value = 'p/h';
  }

  updateKnownRatio(document.getElementById('knownRatioInput').value);
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (currentStep + 1) + '/' + steps.length + ' ' + step.title;
  updateScene();
}

function nextStep() {
  applyStep((currentStep + 1) % steps.length);
}

function prevStep() {
  applyStep((currentStep - 1 + steps.length) % steps.length);
}

updateKnownRatio(document.getElementById('knownRatioInput').value);
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

